/**
 * Each Quadlet unit sees only the keys of commonair.env it needs: the key lists
 * (infra/selfhost/env, generated by scripts/selfhost/unit-env.ts), the units' env lines, and the
 * renderer (scripts/selfhost/render-env.sh) under a real `sh`.
 */
import {
  chmodSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, test } from "vite-plus/test";
import { ALL_ENV_SCHEMAS } from "../../packages/config/src/env.ts";
import {
  APP_UNITS,
  EXTRA_SCHEMAS,
  KEYS_DIR,
  KEYS_HEADER,
  MAIN_TS_SCHEMAS,
  NO_ENV_UNITS,
  RENDER_SCRIPT,
  STATIC_UNITS,
  type SchemaPart,
  appSchemaKeys,
  keysFiles,
  keysPath,
  parseKeysFile,
  partKeys,
  sampleEnv,
  unitEnvLines,
  unitKeyLists,
  unitSetKeys,
} from "../selfhost/unit-env.ts";
import { QUADLET_DIR, readUnitDir, unitSection, unitValues } from "../selfhost/units.ts";
import { shellcheck, shellcheckAvailable } from "./support/shellcheck.ts";

const ROOT = new URL("../../", import.meta.url).pathname;
const read = (p: string) => readFileSync(join(ROOT, p), "utf8");
const RENDER = join(ROOT, RENDER_SCRIPT);
const units = readUnitDir(join(ROOT, QUADLET_DIR));
const unitText = (u: string) => units.get(`commonair-${u}.container`) ?? "";
const containerUnits = [...units.keys()]
  .filter((f) => f.endsWith(".container"))
  .map((f) => f.replace(/^commonair-|\.container$/g, ""));
/** The committed key list of a unit. */
const listed = (u: string) => parseKeysFile(read(keysPath(u)));
const lists = unitKeyLists();

/** Does a key list (with `PREFIX_*` entries) pass this key? */
const passes = (list: string[], key: string) =>
  list.some((e) => (e.endsWith("*") ? key.startsWith(e.slice(0, -1)) : e === key));

/** Non-comment lines of a config or script. */
const code = (text: string, comment = "#") =>
  text
    .split("\n")
    .filter((l) => !l.trimStart().startsWith(comment))
    .join("\n");

describe("the committed key lists", () => {
  test("equal what unit-env.ts generates (run `bun scripts/selfhost/unit-env.ts`)", () => {
    const files = keysFiles();
    for (const [path, text] of files) expect(read(path), path).toBe(text);
    const committed = readdirSync(join(ROOT, KEYS_DIR)).map((f) => `${KEYS_DIR}/${f}`);
    expect(committed.sort()).toEqual([...files.keys()].sort());
  });

  test("--check passes on the committed lists", () => {
    const r = Bun.spawnSync(["bun", join(ROOT, "scripts/selfhost/unit-env.ts"), "--check"]);
    expect(r.exitCode, r.stderr.toString()).toBe(0);
  });

  test("carry an SPDX header and only valid keys", () => {
    for (const unit of lists.keys()) {
      const text = read(keysPath(unit));
      expect(text.startsWith(`${KEYS_HEADER.join("\n")}\n`)).toBe(true);
      for (const k of listed(unit)) expect(k, unit).toMatch(/^[A-Z_][A-Z0-9_]*\*?$/);
      expect(listed(unit).length, unit).toBeGreaterThan(0);
    }
  });
});

describe("every unit", () => {
  test("has a key list or reads no env file at all", () => {
    expect([...lists.keys(), ...NO_ENV_UNITS].sort()).toEqual(containerUnits.sort());
    for (const u of NO_ENV_UNITS) {
      expect(unitValues(unitText(u), "EnvironmentFile"), u).toEqual([]);
      expect(unitValues(unitText(u), "ExecStartPre"), u).toEqual([]);
    }
  });

  test.each([...lists.keys()])("%s: reads only its rendered env file, rendered by ExecStartPre=", (u) => {
    const text = unitText(u);
    const { environmentFile, execStartPre } = unitEnvLines(u);
    expect(unitValues(text, "EnvironmentFile")).toEqual([environmentFile.slice("EnvironmentFile=".length)]);
    expect(unitSection(text, "Container")).toContain(`${environmentFile}\n`);
    // The renderer runs on the host before podman reads the file: a [Service] line.
    expect(unitSection(text, "Service")).toContain(`${execStartPre}\n`);
    // The whole commonair.env is never handed to a container.
    expect(text.split("\n").filter((l) => l.includes("commonair/commonair.env") && !l.startsWith("#"))).toEqual([
      execStartPre,
    ]);
  });
});

describe("our services get what their schemas read", () => {
  test.each([...APP_UNITS])("%s: every key is in the list or set by the unit, and nothing else", (u) => {
    const set = unitSetKeys(unitText(u));
    const list = listed(u);
    const schema = appSchemaKeys(u);
    expect(schema.filter((k) => !list.includes(k) && !set.has(k))).toEqual([]);
    expect(list.filter((k) => !schema.includes(k))).toEqual([]);
    // A key the unit sets would be overridden anyway; listing it only spreads the value.
    expect(list.filter((k) => set.has(k))).toEqual([]);
  });

  test("the derivation follows the schemas: a field added to a schema reaches the unit", () => {
    // Every app unit but media (which picks a few) reads all of coreEnv; each key reaches it.
    for (const u of APP_UNITS.filter((x) => x !== "media")) {
      const got = new Set([...listed(u), ...unitSetKeys(unitText(u))]);
      expect(
        Object.keys(ALL_ENV_SCHEMAS.coreEnv.shape).filter((k) => !got.has(k)),
        u,
      ).toEqual([]);
    }
    // What the sample source sets is every key of every schema, so nothing optional is missed.
    const sample = sampleEnv();
    for (const schema of Object.values(ALL_ENV_SCHEMAS))
      for (const k of Object.keys(schema.shape)) expect(sample[k], k).toBeDefined();
  });

  /** The schema parts of every `loadEnv(...)` call in a main.ts. */
  function mainTsParts(file: string): SchemaPart[] {
    const src = read(file);
    const parts: SchemaPart[] = [];
    for (let i = src.indexOf("loadEnv("); i !== -1; i = src.indexOf("loadEnv(", i + 1)) {
      let depth = 0;
      let end = i + "loadEnv".length;
      for (; end < src.length; end++) {
        if (src[end] === "(") depth++;
        else if (src[end] === ")" && --depth === 0) break;
      }
      const args = src.slice(i + "loadEnv(".length, end);
      for (const m of args.matchAll(/\b([a-z][A-Za-z]*Env|servicePorts)\b(?:\.pick\(\{([^}]*)\}\))?/g)) {
        const name = m[1] as keyof typeof ALL_ENV_SCHEMAS;
        expect(Object.hasOwn(ALL_ENV_SCHEMAS, name), `${file}: ${name}`).toBe(true);
        const pick = m[2] ? [...m[2].matchAll(/([A-Z][A-Z0-9_]*)\s*:/g)].map((p) => p[1] ?? "") : undefined;
        parts.push(pick ? [name, pick] : name);
      }
    }
    return parts;
  }

  test.each(Object.keys(MAIN_TS_SCHEMAS) as (keyof typeof MAIN_TS_SCHEMAS)[])(
    "%s: the mirrored schemas equal the loadEnv calls of its main.ts",
    (u) => {
      const parts = mainTsParts(`services/${u}/src/main.ts`);
      expect(parts.length).toBeGreaterThan(0);
      expect(parts).toEqual(MAIN_TS_SCHEMAS[u]);
      expect(partKeys(parts).sort()).toEqual(appSchemaKeys(u).filter((k) => partKeys(parts).includes(k)));
    },
  );

  test("services that classify networks from process.env get integrityEnv", () => {
    const users = APP_UNITS.filter((u) => {
      const dir = u === "web" ? "apps/web/src" : `services/${u}/src`;
      const files = (Bun.spawnSync(["git", "ls-files", dir], { cwd: ROOT }).stdout.toString() || "")
        .split("\n")
        .filter((f) => f.endsWith(".ts") && !f.endsWith(".test.ts"));
      return files.some((f) => /classifierFromEnv\(|INTEGRITY_DATACENTER_CIDRS_FILE/.test(read(f)));
    });
    expect(users.sort()).toEqual(Object.keys(EXTRA_SCHEMAS).sort());
    for (const u of users) expect(listed(u)).toContain("INTEGRITY_DATACENTER_CIDRS_FILE");
  });

  test("evidence secrets reach only the units ADR 0006 Q4 allows", () => {
    const holders = (key: string) => [...lists.keys()].filter((u) => passes(listed(u), key)).sort();
    expect(holders("EVIDENCE_PRIVATE_KEY")).toEqual(["api"]);
    // storage-init creates (Garage) or checks (external) the evidence key; the worker is the
    // only service that uses it.
    expect(holders("S3_EVIDENCE_ACCESS_KEY_ID")).toEqual(["storage-init", "worker"]);
    expect(holders("S3_EVIDENCE_SECRET_ACCESS_KEY")).toEqual(["storage-init", "worker"]);
  });

  test("DATABASE_URL never comes from the env file: it is a Podman secret", () => {
    for (const u of lists.keys()) expect(listed(u), u).not.toContain("DATABASE_URL");
  });
});

describe("third-party images and tools-image jobs get what they read", () => {
  test("caddy: exactly the placeholders of the Caddyfile, minus what its unit sets (CADDY_LISTEN)", () => {
    const set = unitSetKeys(unitText("caddy"));
    expect(set.has("CADDY_LISTEN")).toBe(true);
    const placeholders = new Set(
      [...code(read("infra/caddy/Caddyfile")).matchAll(/\{\$([A-Z0-9_]+)/g)]
        .map((m) => m[1])
        .filter((k) => !set.has(k!)),
    );
    expect(listed("caddy")).toEqual([...placeholders].toSorted((a, b) => (a ?? "").localeCompare(b ?? "")));
  });

  test("mediamtx: the variables its hooks expand, and its MTX_* settings", () => {
    const vars = [...code(read("infra/mediamtx/mediamtx.yml")).matchAll(/\$([A-Z][A-Z0-9_]*)/g)].map((m) => m[1]!);
    const set = unitSetKeys(unitText("mediamtx"));
    // $MTX_PATH and the other hook variables come from MediaMTX itself.
    expect(vars.filter((v) => !v.startsWith("MTX_") && !set.has(v) && !listed("mediamtx").includes(v))).toEqual([]);
    expect(listed("mediamtx")).toContain("MTX_*");
  });

  test("coturn: exactly the variables infra/coturn/start.sh reads, minus what its unit sets (TURN_PORT)", () => {
    const script = code(read("infra/coturn/start.sh"));
    const set = unitSetKeys(unitText("coturn"));
    expect(set.has("TURN_PORT")).toBe(true);
    // COTURN_BASE_CONF and COTURN_CONF move the files for tests; they are no operator settings.
    const vars = new Set(
      [...script.matchAll(/\$\{?([A-Z][A-Z0-9_]*)/g)]
        .map((m) => m[1]!)
        .filter((v) => !v.startsWith("COTURN_") && !set.has(v)),
    );
    expect(listed("coturn")).toEqual([...vars].sort());
  });

  test("storage-init: every variable optionsFromEnv, storageMode and storeFromEnv read", () => {
    const boot = read("infra/garage/bootstrap.ts");
    const init = read("infra/garage/storage-init.ts");
    const fn = [
      boot.slice(boot.indexOf("export function optionsFromEnv")),
      init.slice(init.indexOf("export function storageMode"), init.indexOf("export interface S3Key")),
      init.slice(init.indexOf("export function storeFromEnv"), init.indexOf("export interface BucketClient")),
    ].join("\n");
    const vars = new Set([
      ...[...fn.matchAll(/env\.([A-Z][A-Z0-9_]*)/g)].map((m) => m[1]!),
      ...[...fn.matchAll(/(?:need|positive)\("([A-Z][A-Z0-9_]*)"/g)].map((m) => m[1]!),
    ]);
    const set = unitSetKeys(unitText("storage-init"));
    expect([...vars].filter((v) => !set.has(v)).sort()).toEqual(listed("storage-init"));
  });

  test("migrate and irc-cert: what their scripts read from process.env, but the secret DATABASE_URL", () => {
    const vars = (files: string[]) =>
      new Set(files.flatMap((f) => [...read(f).matchAll(/process\.env\.([A-Z][A-Z0-9_]*)/g)].map((m) => m[1]!)));
    const migrate = vars(["packages/db/src/migrate.ts", "infra/postgres/apply-app-role.ts"]);
    expect(unitSetKeys(unitText("migrate")).has("DATABASE_URL")).toBe(true);
    migrate.delete("DATABASE_URL");
    expect([...migrate].sort()).toEqual(listed("migrate"));
    expect([...vars(["infra/irc/sync-cert.ts"])]).toEqual(listed("irc-cert"));
  });

  test("postgres: every variable of the image's scripts is listed, set by the unit or the image's own", () => {
    const shell = readdirSync(join(ROOT, "infra/postgres"))
      .filter((f) => f.endsWith(".sh"))
      .map((f) => code(read(`infra/postgres/${f}`)))
      .join("\n");
    const vars = new Set([...shell.matchAll(/\$\{?([A-Z][A-Z0-9_]*)/g)].map((m) => m[1]!));
    // The image sets PG* itself; the health check's knobs exist for tests; the restore target is
    // passed to the one-off restore container (backups.md).
    const own = (v: string) => v.startsWith("PG") || v.startsWith("COMMONAIR_PG_") || v === "RECOVERY_TARGET_TIME";
    const set = unitSetKeys(unitText("postgres"));
    expect([...vars].filter((v) => !own(v) && !set.has(v) && !passes(listed("postgres"), v))).toEqual([]);
  });

  test("garage and grafana", () => {
    expect(listed("garage")).toEqual(["GARAGE_ADMIN_TOKEN", "GARAGE_RPC_SECRET"]);
    expect(read("infra/garage/garage.toml")).not.toMatch(/rpc_secret|admin_token/);
    expect(listed("grafana")).toEqual(["GF_*"]);
    expect(unitValues(unitText("grafana"), "Secret")).toEqual([
      "commonair-grafana-admin-password,type=env,target=GF_SECURITY_ADMIN_PASSWORD",
    ]);
  });

  test("each static list says where it comes from", () => {
    for (const [u, { why }] of Object.entries(STATIC_UNITS)) expect(read(keysPath(u)), u).toContain(why);
  });
});

// --- render-env.sh ------------------------------------------------------------------------

const tmp = () => mkdtempSync(join(tmpdir(), "commonair-render-env-"));
const mode = (p: string) => statSync(p).mode & 0o777;
function render(keys: string, source: string, out: string) {
  const r = Bun.spawnSync(["sh", RENDER, keys, source, out]);
  return { code: r.exitCode, err: r.stderr.toString() };
}

/** commonair.env as install writes it: every .env.example key with a value, plus operator keys. */
function sampleCommonairEnv(): string {
  const keys = read(".env.example")
    .split("\n")
    .filter((l) => /^[A-Z][A-Z0-9_]*=/.test(l))
    .map((l) => l.slice(0, l.indexOf("=")));
  const extra = [
    "MTX_WEBRTCADDITIONALHOSTS",
    "AWS_ACCESS_KEY_ID",
    "AWS_SECRET_ACCESS_KEY",
    "AWS_ENDPOINT",
    "WALG_S3_PREFIX",
    "GF_SERVER_ROOT_URL",
    "SESSION_SECRET",
  ];
  return `${[...keys, ...extra].map((k) => `${k}=value-of-${k}`).join("\n")}\n`;
}

describe("render-env.sh", () => {
  test("renders exactly the listed keys, verbatim, mode 0600 in a 0700 directory", () => {
    const d = tmp();
    writeFileSync(join(d, "list.keys"), "# comment\n\nA\nB_*\n  # indented comment\nC\n");
    const source = [
      "# A=commented out",
      "A=x=y=z",
      `B_ONE="quoted value" with 'spaces' and # hash`,
      "B_TWO=",
      "BX=not a prefix match",
      "C= leading space",
      "  A=indented, podman reads it too",
      "D=secret",
      "AB=not A",
      "A=second A wins in podman, kept in order",
      "",
    ].join("\n");
    writeFileSync(join(d, "commonair.env"), source);
    const out = join(d, "unit-env/commonair-x.env");
    const r = render(join(d, "list.keys"), join(d, "commonair.env"), out);
    expect(r.code, r.err).toBe(0);
    expect(readFileSync(out, "utf8")).toBe(
      [
        "A=x=y=z",
        `B_ONE="quoted value" with 'spaces' and # hash`,
        "B_TWO=",
        "C= leading space",
        "A=indented, podman reads it too",
        "A=second A wins in podman, kept in order",
        "",
      ].join("\n"),
    );
    expect(mode(out)).toBe(0o600);
    expect(mode(join(d, "unit-env"))).toBe(0o700);
    expect(readdirSync(join(d, "unit-env"))).toEqual(["commonair-x.env"]);
  });

  test("an edit of the source shows up on the next render (a unit restart)", () => {
    const d = tmp();
    writeFileSync(join(d, "k"), "A\n");
    writeFileSync(join(d, "src"), "A=1\n");
    expect(render(join(d, "k"), join(d, "src"), join(d, "out")).code).toBe(0);
    writeFileSync(join(d, "src"), "A=2\n");
    expect(render(join(d, "k"), join(d, "src"), join(d, "out")).code).toBe(0);
    expect(readFileSync(join(d, "out"), "utf8")).toBe("A=2\n");
  });

  test("a key in the list but not in the source is simply absent", () => {
    const d = tmp();
    writeFileSync(join(d, "k"), "A\nMISSING\n");
    writeFileSync(join(d, "src"), "A=1\nB=2\n");
    expect(render(join(d, "k"), join(d, "src"), join(d, "out")).code).toBe(0);
    expect(readFileSync(join(d, "out"), "utf8")).toBe("A=1\n");
  });

  describe("fails closed, leaving no env file (not even a stale one)", () => {
    const cases: [string, (d: string) => void][] = [
      ["the source is missing", (d) => writeFileSync(join(d, "k"), "A\n")],
      [
        "the source has no assignment",
        (d) => {
          writeFileSync(join(d, "k"), "A\n");
          writeFileSync(join(d, "src"), "# only a comment\n");
        },
      ],
      ["the key list is missing", (d) => writeFileSync(join(d, "src"), "A=1\n")],
      [
        "the key list is empty",
        (d) => {
          writeFileSync(join(d, "k"), "# nothing\n");
          writeFileSync(join(d, "src"), "A=1\n");
        },
      ],
      [
        "the key list has a bad entry",
        (d) => {
          writeFileSync(join(d, "k"), "A\nB=1\n");
          writeFileSync(join(d, "src"), "A=1\n");
        },
      ],
      [
        "the source is a directory",
        (d) => {
          writeFileSync(join(d, "k"), "A\n");
          mkdirSync(join(d, "src"));
        },
      ],
    ];
    if (process.getuid?.() !== 0)
      cases.push([
        "the source is unreadable",
        (d) => {
          writeFileSync(join(d, "k"), "A\n");
          writeFileSync(join(d, "src"), "A=1\n");
          chmodSync(join(d, "src"), 0o000);
        },
      ]);

    test.each(cases)("%s", (_, setup) => {
      const d = tmp();
      setup(d);
      mkdirSync(join(d, "unit-env"));
      const out = join(d, "unit-env/commonair-x.env");
      writeFileSync(out, "A=stale\n");
      const r = render(join(d, "k"), join(d, "src"), out);
      expect(r.code).not.toBe(0);
      expect(r.err).toMatch(/^render-env: /);
      expect(existsSync(out)).toBe(false);
      expect(readdirSync(join(d, "unit-env"))).toEqual([]);
    });

    test("with the wrong number of arguments", () => {
      expect(Bun.spawnSync(["sh", RENDER, "a", "b"]).exitCode).not.toBe(0);
    });
  });

  test("the committed lists render a full commonair.env to just their keys", () => {
    const d = tmp();
    writeFileSync(join(d, "commonair.env"), sampleCommonairEnv());
    for (const unit of lists.keys()) {
      const out = join(d, `commonair-${unit}.env`);
      const r = render(join(ROOT, keysPath(unit)), join(d, "commonair.env"), out);
      expect(r.code, `${unit}: ${r.err}`).toBe(0);
      const got = readFileSync(out, "utf8")
        .split("\n")
        .filter(Boolean)
        .map((l) => l.slice(0, l.indexOf("=")));
      expect(
        got.filter((k) => !passes(listed(unit), k)),
        unit,
      ).toEqual([]);
    }
  });

  // What a compromise of each non-service container would leak: only these secrets.
  const SECRET_ALLOWLIST: Record<string, string[]> = {
    caddy: [],
    // coturn's static-auth-secret when the TURN relay is on.
    coturn: ["TURN_SHARED_SECRET"],
    garage: ["GARAGE_ADMIN_TOKEN", "GARAGE_RPC_SECRET"],
    "storage-init": [
      "GARAGE_ADMIN_TOKEN",
      "S3_ACCESS_KEY_ID",
      "S3_EVIDENCE_ACCESS_KEY_ID",
      "S3_EVIDENCE_SECRET_ACCESS_KEY",
      "S3_SECRET_ACCESS_KEY",
    ],
    grafana: [],
    "irc-cert": [],
    mediamtx: ["INTERNAL_API_SECRET"],
    migrate: ["POSTGRES_APP_PASSWORD"],
    valkey: ["VALKEY_PASSWORD"],
    postgres: [
      "AWS_ACCESS_KEY_ID",
      "AWS_SECRET_ACCESS_KEY",
      "POSTGRES_PASSWORD",
      "S3_ACCESS_KEY_ID",
      "S3_SECRET_ACCESS_KEY",
    ],
  };
  const SECRET = /PASSWORD|SECRET|_KEY|TOKEN|DATABASE_URL|HMAC|SIGNING/;

  test("lists every non-service unit in the allowlist", () => {
    expect(Object.keys(SECRET_ALLOWLIST).sort()).toEqual(Object.keys(STATIC_UNITS).sort());
  });

  test.each(Object.keys(SECRET_ALLOWLIST))("%s: no secret but the ones it needs", (unit) => {
    const d = tmp();
    writeFileSync(join(d, "commonair.env"), sampleCommonairEnv());
    const out = join(d, "out.env");
    expect(render(join(ROOT, keysPath(unit)), join(d, "commonair.env"), out).code).toBe(0);
    const secrets = readFileSync(out, "utf8")
      .split("\n")
      .map((l) => l.slice(0, l.indexOf("=")))
      .filter((k) => SECRET.test(k));
    expect(secrets.sort()).toEqual(SECRET_ALLOWLIST[unit]);
  });

  test("caddy, the internet-facing proxy, gets no secret at all", () => {
    for (const k of listed("caddy")) expect(k).not.toMatch(SECRET);
  });
});

describe("shellcheck", () => {
  // Skips only on a developer machine with neither; in CI the test runs and fails instead.
  test.skipIf(!shellcheckAvailable && process.env.CI !== "true")(
    "render-env.sh is clean (POSIX sh)",
    () => {
      const r = shellcheck(RENDER);
      expect(r.code, r.out).toBe(0);
    },
    300_000,
  );
});

describe("docs describe the per-unit env", () => {
  // These docs are this unit's to keep current; the README and digitalocean.md limitation bullets
  // are tracked as a contract request until the orchestrator rewrites them.
  const DOCS = [
    "infra/README.md",
    "docs/self-hosting/configuration.md",
    "docs/self-hosting/backups.md",
    "docs/self-hosting/troubleshooting.md",
    "docs/self-hosting/upgrades.md",
    "packages/config/src/env.ts",
  ];
  test.each(DOCS)("%s does not claim every container reads the whole env file", (doc) => {
    const text = readFileSync(join(ROOT, doc), "utf8").replace(/\s+/g, " ");
    expect(text).not.toMatch(/every container reads/i);
    expect(text).not.toMatch(/whole env file/i);
  });
});
